folder=ROOT/'runtime/low-scoped-checkpoints'/batch;folder.mkdir(exist_ok=False)
snap=ROOT/'runtime/cp'/short;snap.mkdir(parents=True,exist_ok=False)

def git(*args,data=None,env=None,optional=False):
 p=subprocess.run(['git','-c','gc.auto=0','-c','maintenance.auto=false',*args],cwd=ROOT,input=data,capture_output=True,env={**os.environ,'GIT_OPTIONAL_LOCKS':'0',**(env or {})},timeout=240)
 if optional and p.returncode:return None
 assert p.returncode==0,(args,p.stderr.decode('utf-8','replace'))
 return p.stdout

if len(sys.argv)>3:
 base=sys.argv[3]
 assert len(base)==40 and all(c in '0123456789abcdef' for c in base)
 evidence=read_json(ROOT/'runtime/checkpoint-low-immediate-v49-20261029.json')
 assert evidence['commit']==base and evidence['status']=='committed_pushed_and_new_originals_verified'
 git('cat-file','-e',base+'^{commit}')
else:
 git('fetch','origin','master');base=git('rev-parse','origin/master').decode().strip()
def committed(path,default=None):
 raw=git('show',base+':'+path,optional=default is not None)
 return json.loads(raw) if raw is not None else default
paths=set();prefix='mod_nailong/data/'
def put(path,body):
 target=snap/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(body);paths.add(path)
def save(path,obj):put(path,(json.dumps(obj,ensure_ascii=False,indent=2)+'\n').encode('utf-8'))
def actual(path):put(path,(ROOT/path).read_bytes())
grant=read_json(ROOT/(prefix+'retry-cooldown-waivers/20261029-remaining-low-immediate.json'))
keys=grant['source_keys'];priority=read_json(ROOT/(prefix+'production-priority.json'))['sources']
assert len(keys)==17 and all(not priority[k]['high_priority'] for k in keys)
rows=committed(prefix+'generated.json');current=read_json(ROOT/(prefix+'generated.json'))
for key in keys:
 if key in current['portraits']:
  rows['portraits'][key]=current['portraits'][key];actual(current['portraits'][key]['image'])
save(prefix+'generated.json',rows)
queue=committed(prefix+'image-retry-queue.json');currentq=read_json(ROOT/(prefix+'image-retry-queue.json'))
for key in keys:
 if key in currentq['sources']:queue['sources'][key]=currentq['sources'][key]
save(prefix+'image-retry-queue.json',queue)
failures=committed(prefix+'generation-failures.json');currentf=read_json(ROOT/(prefix+'generation-failures.json'))
failures['attempts']=[a for a in failures['attempts'] if a['source_sha256'] not in keys]+[a for a in currentf['attempts'] if a['source_sha256'] in keys]
save(prefix+'generation-failures.json',failures)
index=committed(prefix+'fullsize-files.json')
for key in keys:
 journalpath=prefix+'generation-requests/'+key+'.json'
 if not (ROOT/journalpath).exists():continue
 journal=read_json(ROOT/journalpath);actual(journalpath);parent=committed(journalpath,{'attempts':[]})['attempts']
 for a in journal['attempts']:
  actual(a['prompt_file']);assert file_sha256(ROOT/a['prompt_file'])==a['prompt_sha256'] and (ROOT/a['prompt_file']).read_text(encoding='utf-8')==a['prompt']
  v=a.get('actual_request_verification')
  if v:
   ledger=read_json(ROOT/f'runtime/production-queue/dispatch/{key}-{a["number"]:03}.json');payload=read_json(Path(ledger['actual_request_snapshot_file']))
   assert file_sha256(Path(ledger['actual_request_snapshot_file']))==v['actual_request_snapshot_sha256']==ledger['actual_request_snapshot_sha256']
   assert payload['prompt']==a['prompt'] and payload['transparent']==v['transparent_background'] and [file_sha256(Path(p)) for p in payload['references']]==v['input_sha256']
   if a.get('fullsize_sha256'):assert ledger['status']=='returned_image' and ledger['returned_image_sha256']==a['fullsize_sha256']==file_sha256(Path(ledger['returned_image']))
   proof=prefix+f'production-call-proofs/{key}-{a["number"]:03}-{v["actual_request_snapshot_sha256"][:12]}.json'
   save(proof,{'machine_id':machine_id(),'actual_request_verification':v,'actual_payload':payload,'dispatch_ledger':ledger,'scope':'Retained exact pre-call payload and returned terminal proof. This copy is post-call, with original reliable timestamps intact; no replay or backdated recording.'})
  if a.get('fullsize_sha256'):classify_returned_attempt(a,parent,index['outputs'],machine_id())
expected,_,provenance=recorded_outputs(snap/'mod_nailong');digests=expected-set(index['outputs']);masters=[]
for digest in sorted(digests):
 source=ROOT/master_path(digest)
 with Image.open(source) as image:size=list(image.size);mode=image.mode
 masters.append({'path':str(source),'sha256':digest,'bytes':source.stat().st_size,'size':size,'mode':mode,'provenance':provenance[digest]})
new=sync_git({'current_masters_missing':[],'historical_fullsize_sha_missing':[],'masters':masters},root=snap)
new['outputs']={**index['outputs'],**new['outputs']};new['count']=len(new['outputs']);new['original_png_bytes']=sum(e['bytes'] for e in new['outputs'].values())
save(prefix+'fullsize-files.json',new);paths|={master_path(d) for d in digests}
for group in range(148,170):
 for p in (ROOT/'mod_nailong/data').rglob(f'*rollinga{group}*.json'):
  actual(p.relative_to(ROOT).as_posix())
for key in keys:
 for p in (ROOT/(prefix+'retry-approval-versions')).glob(key+'-*.json'):actual(p.relative_to(ROOT).as_posix())
for pattern in ['production-resumptions/20261029-low-v4[789]*.json','production-resumptions/20261029-v47-*.json','production-resumptions/20261029-v48-*.json','production-resumptions/20261029-v49-*.json','production-resumptions/20261029-four-terminal-*.json','production-checkpoint-failures/20261029-v47-*.json','production-transport-retries/low-terminal-recovery-20261029-*.json','production-preparation-receipts/20261029-terminal-service-*.json','production-window-timings/resume-20261025-large-logical-queue-v4[789]-*.json','retry-scheduler-batches/cooldown-19*.json','retry-scheduler-batches/cooldown-20*.json']:
 for p in (ROOT/'mod_nailong/data').glob(pattern):actual(p.relative_to(ROOT).as_posix())
for pattern in ['production-resumptions/20261029-low-v5*.json','production-resumptions/20261029-v5*-*.json','production-window-timings/resume-20261025-large-logical-queue-v5*-*.json','retry-scheduler-batches/cooldown-2*.json','production-retry-approval-merges/20261029-two-art-v50.json','production-checkpoint-failures/20261029-v49-git-*.json','production-delivery-receipts/20261029-low-immediate-*.json','production-network-recovery-evidence/20261029-v50-*.json','production-preparation-receipts/20261029-v50-terminal-service-*.json','production-transport-retries/low-v50-terminal-recovery-20261029-*.json','independent-art-tasks/20261029-arabia-*.json','production-original-replacements/low-arabia-original-method-20261029*.json']:
 for p in (ROOT/'mod_nailong/data').glob(pattern):actual(p.relative_to(ROOT).as_posix())
for version in (48,49,50,51,52):
 for path in [f'docs/handoffs/2026-10-29-low-v{version}-helper-sources.json',prefix+f'production-resumptions/20261029-low-v{version}.json']:
  if (ROOT/path).exists():actual(path)
for path in ['tools/prepare_reviewed_terminal_service_retry.py','tools/production_prepare_boundary.py','tests/test_reviewed_terminal_service_retry.py','tools/prepare_reviewed_original_replacements.py','tests/test_original_replacement_preparation.py']:
 actual(path)
for path in [prefix+'exact-retry-two-art-v50-20261029-reviewed.json']:
 if (ROOT/path).exists():actual(path)
counts={}
for high,tier in ((True,'HIGH'),(False,'LOW')):
 tierkeys=[k for k,v in priority.items() if v['high_priority']==high];approved=sum(rows['portraits'].get(k,{}).get('review')=='approved' for k in tierkeys)
 counts[tier]={'approved':approved,'total':len(tierkeys),'percent':100*approved/len(tierkeys)}
save(prefix+f'production-progress-snapshots/{batch}.json',{'machine_id':machine_id(),'observed_at_utc':utc_now(),'counts':counts,'scope':'Approved SHA-bound art rows in this exact scoped Git snapshot; not game validation or a publication claim.'})
save(prefix+f'production-checkpoint-failures/{batch}-assembly.json',{'machine_id':machine_id(),'observed_at_utc':utc_now(),'public_parent':base,'selected_low_keys':keys,'focused_tests_passed':126,'assembly_source':Path(__file__).read_text(encoding='utf-8'),'scope':'Only seventeen authorized LOW sources and this task evidence above public master. All returned PNGs including art rejects retained byte-for-byte. Primary working tree, index, ref, and colleague private commits untouched.'})
env={'GIT_INDEX_FILE':str(folder/'alternate.index')};git('read-tree',base,env=env)
ordered=sorted(paths);oids=git('hash-object','-w','--stdin-paths',data=''.join((snap/p).as_posix()+'\n' for p in ordered).encode()).decode().splitlines();assert len(oids)==len(ordered)
git('update-index','--index-info',env=env,data=''.join('100644 '+oid+'\t'+p+'\n' for p,oid in zip(ordered,oids)).encode());git('diff','--cached','--check',base,env=env)
tree=git('write-tree',env=env).decode().strip();commit=git('commit-tree',tree,'-p',base,'-m','Preserve immediate LOW production and network recovery evidence').decode().strip()
receipt={'machine_id':machine_id(),'completed_at_utc':utc_now(),'batch':batch,'parent_commit':base,'public_base_commit':base,'commit':commit,'status':'committed_push_pending','paths':ordered,'new_original_PNGs':len(digests),'new_original_bytes':sum(new['outputs'][d]['bytes'] for d in digests),'snapshot':snap.relative_to(ROOT).as_posix(),'primary_ref_index_untouched':True,'scope':'Task-only private commit above fixed public parent; no push or remote byte-readback claim.'}
write_json(folder/'receipt.json',receipt);write_json(ROOT/f'runtime/checkpoint-{batch}.json',receipt)
print(json.dumps({k:v for k,v in receipt.items() if k!='paths'}))
